INSERT INTO exercises (id, name_en, name_de, desc_en, desc_de, primary_muscles, secondary_muscles, equipment, tracking, category) VALUES
('barbell-back-squat', 'Back Squat', 'Kniebeuge', 'Rest the bar on your upper back, feet about shoulder-width apart, and sit down until your hips are at least level with your knees. Drive up through the whole foot. Key cue: brace your core and keep your knees tracking over your toes.', 'Lege die Stange auf den oberen Rücken, stelle die Füße etwa schulterbreit und setze dich ab, bis die Hüfte mindestens auf Kniehöhe ist. Drücke dich über den ganzen Fuß nach oben. Wichtig: Rumpf anspannen und die Knie in Richtung der Zehen führen.', '["quads","glutes"]', '["hamstrings","lower_back","adductors","abs"]', 'barbell', 'weight_reps', 'strength'),
('barbell-front-squat', 'Front Squat', 'Frontkniebeuge', 'Hold the bar on the front of your shoulders with high elbows and squat down with an upright torso. Stand back up without letting the elbows drop. Key cue: elbows up, chest proud.', 'Halte die Stange vorn auf den Schultern, die Ellbogen hoch, und beuge die Knie mit aufrechtem Oberkörper. Stehe wieder auf, ohne die Ellbogen sinken zu lassen. Wichtig: Ellbogen hoch, Brust raus.', '["quads"]', '["glutes","abs","upper_back"]', 'barbell', 'weight_reps', 'strength'),
('barbell-bench-press', 'Bench Press', 'Bankdrücken', 'Lie on the bench with your eyes under the bar, lower it under control to your mid-chest and press it back up. Keep your feet planted. Key cue: pull your shoulder blades together and down before you unrack.', 'Lege dich so auf die Bank, dass die Augen unter der Stange sind, senke sie kontrolliert zur Brustmitte und drücke sie wieder hoch. Die Füße bleiben fest am Boden. Wichtig: Schulterblätter vor dem Ausheben nach hinten unten ziehen.', '["chest"]', '["triceps","shoulders"]', 'barbell', 'weight_reps', 'strength'),
('barbell-incline-bench-press', 'Incline Bench Press', 'Schrägbankdrücken', 'Set the bench to 30–45 degrees, lower the bar to your upper chest and press it up over your shoulders. Key cue: keep your wrists stacked over your elbows.', 'Stelle die Bank auf 30–45 Grad, senke die Stange zur oberen Brust und drücke sie über die Schultern nach oben. Wichtig: Handgelenke bleiben über den Ellbogen.', '["chest","shoulders"]', '["triceps"]', 'barbell', 'weight_reps', 'strength'),
('barbell-close-grip-bench-press', 'Close-Grip Bench Press', 'Enges Bankdrücken', 'Grip the bar about shoulder-width, lower it to your lower chest and press up. Key cue: keep your elbows tucked close to your ribs.', 'Greife die Stange etwa schulterbreit, senke sie zur unteren Brust und drücke sie hoch. Wichtig: Ellbogen eng am Körper halten.', '["triceps"]', '["chest","shoulders"]', 'barbell', 'weight_reps', 'strength'),
('barbell-deadlift', 'Deadlift', 'Kreuzheben', 'Stand with the bar over your mid-foot, hinge down, grip it and stand up by pushing the floor away. Lower it the same way. Key cue: flat back, bar stays in contact with your legs.', 'Stelle dich so hin, dass die Stange über dem Mittelfuß liegt, beuge dich mit der Hüfte nach unten, greife sie und stehe auf, indem du den Boden wegdrückst. Senke sie genauso wieder ab. Wichtig: gerader Rücken, die Stange bleibt an den Beinen.', '["hamstrings","glutes","lower_back"]', '["quads","traps","forearms","lats"]', 'barbell', 'weight_reps', 'strength'),
('barbell-sumo-deadlift', 'Sumo Deadlift', 'Sumo-Kreuzheben', 'Take a wide stance with toes turned out, grip the bar inside your knees and stand up tall. Key cue: push your knees out and keep your chest up.', 'Nimm einen breiten Stand mit nach außen gedrehten Zehen, greife die Stange innerhalb der Knie und richte dich auf. Wichtig: Knie nach außen drücken und die Brust oben halten.', '["glutes","quads","adductors"]', '["hamstrings","lower_back","traps","forearms"]', 'barbell', 'weight_reps', 'strength'),
('barbell-romanian-deadlift', 'Romanian Deadlift', 'Rumänisches Kreuzheben', 'From standing, push your hips back with soft knees and lower the bar along your thighs until you feel a strong hamstring stretch. Drive your hips forward to stand. Key cue: the movement comes from the hips, not the knees.', 'Schiebe aus dem Stand die Hüfte mit leicht gebeugten Knien nach hinten und senke die Stange an den Oberschenkeln entlang, bis die Beinrückseite deutlich gedehnt ist. Strecke die Hüfte, um aufzustehen. Wichtig: Die Bewegung kommt aus der Hüfte, nicht aus den Knien.', '["hamstrings","glutes"]', '["lower_back","forearms"]', 'barbell', 'weight_reps', 'strength'),
('barbell-overhead-press', 'Overhead Press', 'Schulterdrücken', 'Press the bar from your collarbone straight overhead until your arms are locked out, then lower it under control. Key cue: squeeze your glutes so your lower back does not arch.', 'Drücke die Stange vom Schlüsselbein gerade über den Kopf, bis die Arme gestreckt sind, und senke sie kontrolliert ab. Wichtig: Po anspannen, damit du nicht ins Hohlkreuz fällst.', '["shoulders"]', '["triceps","traps","abs"]', 'barbell', 'weight_reps', 'strength'),
('barbell-push-press', 'Push Press', 'Stoßdrücken', 'Dip slightly at the knees, then drive up explosively and use that momentum to press the bar overhead. Key cue: the dip is short and straight down, with heels on the floor.', 'Gehe kurz in die Knie, strecke dich explosiv und nutze den Schwung, um die Stange über den Kopf zu drücken. Wichtig: Die Kniebeuge ist kurz und senkrecht, die Fersen bleiben am Boden.', '["shoulders"]', '["triceps","quads","glutes"]', 'barbell', 'weight_reps', 'strength'),
('barbell-bent-over-row', 'Bent-Over Row', 'Vorgebeugtes Rudern', 'Hinge forward with a flat back and pull the bar to your lower ribs, then lower it fully. Key cue: lead with your elbows and avoid jerking with your torso.', 'Beuge dich mit geradem Rücken vor und ziehe die Stange zu den unteren Rippen, dann senke sie vollständig ab. Wichtig: Ziehe mit den Ellbogen und hole keinen Schwung mit dem Oberkörper.', '["lats","upper_back"]', '["biceps","lower_back","forearms"]', 'barbell', 'weight_reps', 'strength'),
('barbell-t-bar-row', 'T-Bar Row', 'T-Bar-Rudern', 'Straddle the bar anchored at one end, hinge forward and pull the loaded end to your chest. Key cue: squeeze your shoulder blades together at the top.', 'Stelle dich über die einseitig fixierte Stange, beuge dich vor und ziehe das beladene Ende zur Brust. Wichtig: Schulterblätter oben zusammenziehen.', '["upper_back","lats"]', '["biceps","lower_back"]', 'barbell', 'weight_reps', 'strength'),
('barbell-hip-thrust', 'Hip Thrust', 'Hip Thrust', 'Lean your upper back against a bench with the bar over your hips and drive your hips up until your torso is parallel to the floor. Key cue: tuck your chin and pause at the top with full glute squeeze.', 'Lehne den oberen Rücken an eine Bank, die Stange liegt über der Hüfte, und drücke die Hüfte hoch, bis der Oberkörper waagerecht ist. Wichtig: Kinn zur Brust und oben kurz mit voller Po-Spannung halten.', '["glutes"]', '["hamstrings","quads"]', 'barbell', 'weight_reps', 'strength'),
('barbell-curl', 'Barbell Curl', 'Langhantel-Curl', 'Stand tall, curl the bar up to your shoulders and lower it slowly. Key cue: elbows stay pinned to your sides – no swinging.', 'Stehe aufrecht, beuge die Arme und führe die Stange zu den Schultern, dann senke sie langsam ab. Wichtig: Ellbogen bleiben am Körper – kein Schwung.', '["biceps"]', '["forearms"]', 'barbell', 'weight_reps', 'strength'),
('barbell-skull-crusher', 'Skull Crusher', 'Stirndrücken', 'Lie on a bench, hold the bar over your chest and bend only your elbows to lower it towards your forehead, then extend. Key cue: upper arms stay still and vertical.', 'Lege dich auf eine Bank, halte die Stange über der Brust und beuge nur die Ellbogen, um sie zur Stirn zu senken; dann strecke die Arme. Wichtig: Die Oberarme bleiben ruhig und senkrecht.', '["triceps"]', '["forearms"]', 'barbell', 'weight_reps', 'strength'),
('barbell-lunge', 'Barbell Lunge', 'Langhantel-Ausfallschritt', 'With the bar on your back, step forward and lower your back knee towards the floor, then push back to standing. Key cue: keep your torso upright and your front heel down.', 'Mache mit der Stange auf dem Rücken einen Schritt nach vorn, senke das hintere Knie Richtung Boden und drücke dich zurück in den Stand. Wichtig: Oberkörper aufrecht, vordere Ferse bleibt am Boden.', '["quads","glutes"]', '["hamstrings","adductors","abs"]', 'barbell', 'weight_reps', 'strength'),
('barbell-good-morning', 'Good Morning', 'Good Morning', 'With the bar on your upper back, push your hips back and bow forward with a flat back, then stand up. Key cue: start light and keep a slight bend in the knees.', 'Schiebe mit der Stange auf dem oberen Rücken die Hüfte nach hinten und beuge dich mit geradem Rücken vor, dann richte dich auf. Wichtig: Leicht anfangen und die Knie minimal gebeugt lassen.', '["hamstrings","lower_back"]', '["glutes"]', 'barbell', 'weight_reps', 'strength'),
('barbell-power-clean', 'Power Clean', 'Power Clean', 'Pull the bar from the floor, extend your hips explosively and catch it on your shoulders in a quarter squat. Key cue: jump with the bar close to your body, then whip your elbows through.', 'Ziehe die Stange vom Boden, strecke die Hüfte explosiv und fange sie in der Viertelkniebeuge auf den Schultern. Wichtig: Mit der Stange nah am Körper abspringen, dann die Ellbogen schnell nach vorn bringen.', '["glutes","hamstrings","traps"]', '["quads","shoulders","lower_back","calves"]', 'barbell', 'weight_reps', 'strength'),
('barbell-shrug', 'Barbell Shrug', 'Langhantel-Schulterheben', 'Hold the bar with straight arms and lift your shoulders straight up towards your ears, pause, and lower. Key cue: no rolling – just straight up and down.', 'Halte die Stange mit gestreckten Armen und ziehe die Schultern gerade Richtung Ohren, kurz halten, absenken. Wichtig: Nicht kreisen – nur gerade hoch und runter.', '["traps"]', '["forearms"]', 'barbell', 'weight_reps', 'strength'),
('barbell-landmine-press', 'Landmine Press', 'Landmine-Drücken', 'Hold the free end of an anchored bar at your shoulder and press it up and forward until your arm is straight. Key cue: stay tall and do not lean back.', 'Halte das freie Ende einer fixierten Stange an der Schulter und drücke es nach vorn oben, bis der Arm gestreckt ist. Wichtig: Aufrecht bleiben und nicht nach hinten lehnen.', '["shoulders","chest"]', '["triceps","abs"]', 'barbell', 'weight_reps', 'strength')
INSERT INTO exercises (id, name_en, name_de, desc_en, desc_de, primary_muscles, secondary_muscles, equipment, tracking, category) VALUES
('dumbbell-bench-press', 'Dumbbell Bench Press', 'Kurzhantel-Bankdrücken', 'Lie on a bench and press both dumbbells up from chest height until your arms are straight, then lower with control. Key cue: elbows at roughly 45 degrees to your torso.', 'Lege dich auf eine Bank und drücke beide Kurzhanteln von Brusthöhe nach oben, bis die Arme gestreckt sind; kontrolliert absenken. Wichtig: Ellbogen etwa 45 Grad vom Oberkörper abspreizen.', '["chest"]', '["triceps","shoulders"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-incline-press', 'Incline Dumbbell Press', 'Kurzhantel-Schrägbankdrücken', 'On a 30–45 degree bench, press the dumbbells from your upper chest up over your shoulders. Key cue: keep your shoulder blades pulled back against the bench.', 'Drücke auf einer 30–45 Grad geneigten Bank die Kurzhanteln von der oberen Brust über die Schultern. Wichtig: Schulterblätter bleiben nach hinten an die Bank gezogen.', '["chest","shoulders"]', '["triceps"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-fly', 'Dumbbell Fly', 'Kurzhantel-Fliegende', 'Lying on a bench, open your arms wide with slightly bent elbows until you feel a chest stretch, then bring the dumbbells back together. Key cue: hug a big tree – the elbow angle stays fixed.', 'Öffne auf der Bank liegend die Arme weit mit leicht gebeugten Ellbogen, bis die Brust gedehnt ist, und führe die Hanteln wieder zusammen. Wichtig: Stell dir vor, du umarmst einen dicken Baum – der Ellbogenwinkel bleibt gleich.', '["chest"]', '["shoulders"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-shoulder-press', 'Dumbbell Shoulder Press', 'Kurzhantel-Schulterdrücken', 'Sitting or standing, press the dumbbells from shoulder height straight overhead and lower them again. Key cue: ribs down, no leaning back.', 'Drücke im Sitzen oder Stehen die Kurzhanteln von Schulterhöhe gerade über den Kopf und senke sie wieder ab. Wichtig: Rippen unten lassen, nicht nach hinten lehnen.', '["shoulders"]', '["triceps","traps"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-arnold-press', 'Arnold Press', 'Arnold-Press', 'Start with the dumbbells in front of your shoulders, palms facing you, and rotate your palms forward as you press overhead. Reverse on the way down. Key cue: one smooth rotation, no pause halfway.', 'Starte mit den Kurzhanteln vor den Schultern, Handflächen zu dir, und drehe die Handflächen beim Hochdrücken nach vorn. Auf dem Rückweg umgekehrt. Wichtig: eine flüssige Drehung ohne Pause.', '["shoulders"]', '["triceps","traps"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-lateral-raise', 'Lateral Raise', 'Seitheben', 'Raise the dumbbells out to your sides until your arms are level with your shoulders, then lower slowly. Key cue: lead with your elbows and keep the weights light.', 'Hebe die Kurzhanteln seitlich an, bis die Arme auf Schulterhöhe sind, und senke sie langsam ab. Wichtig: Die Ellbogen führen, und lieber leichte Gewichte nehmen.', '["shoulders"]', '["traps"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-front-raise', 'Front Raise', 'Frontheben', 'Lift the dumbbells in front of you to shoulder height with nearly straight arms and lower under control. Key cue: do not swing your torso.', 'Hebe die Kurzhanteln mit fast gestreckten Armen vor dem Körper auf Schulterhöhe und senke sie kontrolliert ab. Wichtig: Kein Schwung mit dem Oberkörper.', '["shoulders"]', '["chest"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-rear-delt-fly', 'Rear Delt Fly', 'Vorgebeugtes Seitheben', 'Hinge forward with a flat back and raise the dumbbells out to the sides, squeezing the back of your shoulders. Key cue: pinkies up, neck relaxed.', 'Beuge dich mit geradem Rücken vor und hebe die Kurzhanteln seitlich an, dabei die hintere Schulter anspannen. Wichtig: Kleine Finger nach oben, Nacken locker.', '["shoulders","upper_back"]', '["traps"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-row', 'One-Arm Dumbbell Row', 'Einarmiges Kurzhantel-Rudern', 'Support one hand and knee on a bench and pull the dumbbell up to your hip, then lower it fully. Key cue: pull the elbow back towards your pocket and keep your hips square.', 'Stütze eine Hand und ein Knie auf einer Bank ab und ziehe die Kurzhantel zur Hüfte, dann ganz absenken. Wichtig: Ziehe den Ellbogen Richtung Hosentasche und halte die Hüfte gerade.', '["lats","upper_back"]', '["biceps","forearms"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-curl', 'Dumbbell Curl', 'Kurzhantel-Curl', 'Curl the dumbbells up while turning your palms towards your shoulders, then lower slowly. Key cue: upper arms stay still.', 'Beuge die Arme und drehe die Handflächen dabei zu den Schultern, dann langsam absenken. Wichtig: Die Oberarme bleiben ruhig.', '["biceps"]', '["forearms"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-hammer-curl', 'Hammer Curl', 'Hammer-Curl', 'Curl the dumbbells with your palms facing each other the whole way, like holding two hammers. Key cue: no swinging, squeeze at the top.', 'Beuge die Arme, während die Handflächen die ganze Zeit zueinander zeigen – als würdest du zwei Hämmer halten. Wichtig: Kein Schwung, oben kurz anspannen.', '["biceps","forearms"]', '[]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-concentration-curl', 'Concentration Curl', 'Konzentrations-Curl', 'Sit down, rest your elbow against your inner thigh and curl one dumbbell up to your shoulder. Key cue: slow on the way down.', 'Setze dich, stütze den Ellbogen an der Oberschenkelinnenseite ab und beuge den Arm mit einer Kurzhantel bis zur Schulter. Wichtig: Langsam ablassen.', '["biceps"]', '[]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-overhead-triceps-extension', 'Overhead Triceps Extension', 'Trizepsstrecken über Kopf', 'Hold one dumbbell with both hands overhead, lower it behind your head by bending your elbows and extend again. Key cue: elbows point forward, not out.', 'Halte eine Kurzhantel mit beiden Händen über dem Kopf, senke sie durch Beugen der Ellbogen hinter den Kopf und strecke die Arme wieder. Wichtig: Ellbogen zeigen nach vorn, nicht zur Seite.', '["triceps"]', '[]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-triceps-kickback', 'Triceps Kickback', 'Trizeps-Kickback', 'Hinge forward, keep your upper arm parallel to the floor and straighten your elbow to push the dumbbell back. Key cue: only the forearm moves.', 'Beuge dich vor, halte den Oberarm parallel zum Boden und strecke den Ellbogen, um die Kurzhantel nach hinten zu führen. Wichtig: Nur der Unterarm bewegt sich.', '["triceps"]', '[]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-goblet-squat', 'Goblet Squat', 'Goblet-Kniebeuge', 'Hold one dumbbell upright against your chest and squat down between your knees, then stand up. Key cue: elbows inside the knees, chest up.', 'Halte eine Kurzhantel senkrecht vor der Brust, beuge die Knie tief und stehe wieder auf. Wichtig: Ellbogen innerhalb der Knie, Brust oben.', '["quads","glutes"]', '["abs","adductors"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-lunge', 'Dumbbell Lunge', 'Kurzhantel-Ausfallschritt', 'Holding a dumbbell in each hand, step forward, lower your back knee and push back up. Key cue: long enough step so the front knee stays over the foot.', 'Mache mit je einer Kurzhantel in der Hand einen Schritt nach vorn, senke das hintere Knie und drücke dich zurück. Wichtig: Der Schritt ist lang genug, damit das vordere Knie über dem Fuß bleibt.', '["quads","glutes"]', '["hamstrings","adductors"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-bulgarian-split-squat', 'Bulgarian Split Squat', 'Bulgarische Kniebeuge', 'Place your rear foot on a bench behind you and squat down on the front leg, then drive up. Key cue: most of the weight stays on the front heel.', 'Lege den hinteren Fuß auf einer Bank ab, beuge das vordere Bein und drücke dich wieder hoch. Wichtig: Das Gewicht liegt überwiegend auf der vorderen Ferse.', '["quads","glutes"]', '["hamstrings","adductors"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-romanian-deadlift', 'Dumbbell Romanian Deadlift', 'Rumänisches Kreuzheben mit Kurzhanteln', 'Push your hips back with soft knees and slide the dumbbells down your thighs, then stand up by driving the hips forward. Key cue: back stays flat, weights stay close.', 'Schiebe die Hüfte mit leicht gebeugten Knien nach hinten und führe die Kurzhanteln an den Oberschenkeln nach unten; strecke die Hüfte zum Aufstehen. Wichtig: Rücken gerade, Gewichte nah am Körper.', '["hamstrings","glutes"]', '["lower_back","forearms"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-shrug', 'Dumbbell Shrug', 'Kurzhantel-Schulterheben', 'With a dumbbell in each hand, lift your shoulders straight up, pause and lower. Key cue: arms stay long, the traps do the work.', 'Ziehe mit je einer Kurzhantel in der Hand die Schultern gerade nach oben, kurz halten, absenken. Wichtig: Die Arme bleiben lang, der Nacken arbeitet.', '["traps"]', '["forearms"]', 'dumbbell', 'weight_reps', 'strength'),
('dumbbell-pullover', 'Dumbbell Pullover', 'Kurzhantel-Überzug', 'Lie on a bench, hold one dumbbell over your chest and lower it in an arc behind your head, then pull it back. Key cue: slight elbow bend and ribs down.', 'Lege dich auf eine Bank, halte eine Kurzhantel über der Brust und senke sie im Bogen hinter den Kopf, dann ziehe sie zurück. Wichtig: Ellbogen leicht gebeugt, Rippen unten.', '["lats","chest"]', '["triceps"]', 'dumbbell', 'weight_reps', 'strength')
INSERT INTO exercises (id, name_en, name_de, desc_en, desc_de, primary_muscles, secondary_muscles, equipment, tracking, category) VALUES
('dumbbell-farmers-carry', 'Farmer''s Carry', 'Farmer’s Walk', 'Pick up two heavy dumbbells and walk with short, quick steps for time. Key cue: stand tall, shoulders back, do not let the weights sway.', 'Nimm zwei schwere Kurzhanteln auf und gehe mit kurzen, schnellen Schritten auf Zeit. Wichtig: Aufrecht bleiben, Schultern zurück, die Gewichte nicht pendeln lassen.', '["forearms","traps"]', '["abs","glutes","calves"]', 'dumbbell', 'time', 'strength'),
('kettlebell-swing', 'Kettlebell Swing', 'Kettlebell-Swing', 'Hike the kettlebell back between your legs and snap your hips forward so it floats up to chest height. Key cue: it is a hip hinge, not a squat – your arms are just ropes.', 'Schwinge die Kettlebell zwischen den Beinen nach hinten und strecke die Hüfte explosiv, sodass sie bis auf Brusthöhe schwebt. Wichtig: Die Bewegung kommt aus der Hüfte, nicht aus den Knien – die Arme sind nur Seile.', '["glutes","hamstrings"]', '["lower_back","shoulders","abs","forearms"]', 'kettlebell', 'weight_reps', 'strength'),
('kettlebell-goblet-squat', 'Kettlebell Goblet Squat', 'Kettlebell-Goblet-Kniebeuge', 'Hold the kettlebell by the horns at your chest and squat deep, then stand up. Key cue: keep the bell close and your chest tall.', 'Halte die Kettlebell an den Griffseiten vor der Brust, gehe tief in die Kniebeuge und stehe wieder auf. Wichtig: Kettlebell nah am Körper, Brust aufrecht.', '["quads","glutes"]', '["abs","adductors"]', 'kettlebell', 'weight_reps', 'strength'),
('kettlebell-turkish-get-up', 'Turkish Get-Up', 'Turkish Get-Up', 'Lying on your back with the kettlebell locked out above you, stand up step by step and reverse the sequence back down. Key cue: eyes on the bell and arm vertical the whole time.', 'Stehe aus der Rückenlage mit gestreckt gehaltener Kettlebell Schritt für Schritt auf und kehre genauso zurück. Wichtig: Blick zur Kettlebell, der Arm bleibt die ganze Zeit senkrecht.', '["shoulders","abs"]', '["glutes","obliques","quads","triceps"]', 'kettlebell', 'weight_reps', 'strength'),
('kettlebell-snatch', 'Kettlebell Snatch', 'Kettlebell-Snatch', 'Swing the kettlebell back and pull it in one motion to a locked-out arm overhead. Key cue: punch your hand through at the top so the bell lands softly.', 'Schwinge die Kettlebell nach hinten und bringe sie in einer Bewegung über den Kopf in den gestreckten Arm. Wichtig: Oben die Hand durchstoßen, damit die Kettlebell weich landet.', '["shoulders","glutes"]', '["hamstrings","traps","forearms","abs"]', 'kettlebell', 'weight_reps', 'strength'),
('kettlebell-clean-and-press', 'Kettlebell Clean & Press', 'Kettlebell Clean & Press', 'Clean the kettlebell to the rack position at your shoulder, then press it overhead and lower it back down. Key cue: keep the wrist straight and the forearm vertical.', 'Bringe die Kettlebell in die Rack-Position an der Schulter, drücke sie über den Kopf und senke sie wieder ab. Wichtig: Handgelenk gerade, Unterarm senkrecht.', '["shoulders","glutes"]', '["triceps","hamstrings","abs","forearms"]', 'kettlebell', 'weight_reps', 'strength'),
('kettlebell-deadlift', 'Kettlebell Deadlift', 'Kettlebell-Kreuzheben', 'Stand over the kettlebell, hinge down with a flat back, grip the handle and stand up tall. Key cue: push your hips back as if closing a door with them.', 'Stelle dich über die Kettlebell, beuge dich mit geradem Rücken aus der Hüfte, greife den Griff und richte dich auf. Wichtig: Hüfte nach hinten schieben, als würdest du damit eine Tür schließen.', '["hamstrings","glutes"]', '["lower_back","forearms","quads"]', 'kettlebell', 'weight_reps', 'strength'),
('kettlebell-windmill', 'Kettlebell Windmill', 'Kettlebell-Windmühle', 'Hold the kettlebell overhead, push your hip out to that side and reach your free hand down the opposite leg. Key cue: keep looking up at the bell.', 'Halte die Kettlebell über dem Kopf, schiebe die Hüfte zur gleichen Seite und führe die freie Hand am anderen Bein nach unten. Wichtig: Der Blick bleibt an der Kettlebell.', '["obliques","shoulders"]', '["hamstrings","glutes","abs"]', 'kettlebell', 'weight_reps', 'strength'),
('kettlebell-halo', 'Kettlebell Halo', 'Kettlebell-Halo', 'Hold the kettlebell upside down by the horns and circle it closely around your head, alternating direction. Key cue: ribs down, head stays still.', 'Halte die Kettlebell kopfüber an den Griffseiten und kreise sie eng um den Kopf, die Richtung wechselt. Wichtig: Rippen unten, der Kopf bleibt ruhig.', '["shoulders"]', '["traps","abs","triceps"]', 'kettlebell', 'weight_reps', 'strength'),
('band-pull-apart', 'Band Pull-Apart', 'Band Pull-Apart', 'Hold a band at chest height with straight arms and pull it apart until it touches your chest. Key cue: squeeze your shoulder blades, do not shrug.', 'Halte ein Band mit gestreckten Armen auf Brusthöhe und ziehe es auseinander, bis es die Brust berührt. Wichtig: Schulterblätter zusammenziehen, Schultern nicht hochziehen.', '["upper_back","shoulders"]', '["traps"]', 'band', 'reps', 'strength'),
('band-squat', 'Banded Squat', 'Kniebeuge mit Band', 'Stand on the band, loop it over your shoulders and squat as usual against the growing resistance. Key cue: push your knees out against the band.', 'Stelle dich auf das Band, lege es über die Schultern und mache Kniebeugen gegen den steigenden Widerstand. Wichtig: Knie gegen den Zug nach außen drücken.', '["quads","glutes"]', '["hamstrings","adductors"]', 'band', 'reps', 'strength'),
('band-row', 'Band Row', 'Rudern mit Band', 'Anchor the band in front of you and pull both ends towards your ribs, then return slowly. Key cue: chest tall, elbows brush your sides.', 'Befestige das Band vor dir und ziehe beide Enden zu den Rippen, dann langsam zurück. Wichtig: Brust aufrecht, Ellbogen streifen den Körper.', '["lats","upper_back"]', '["biceps"]', 'band', 'reps', 'strength'),
('band-chest-press', 'Band Chest Press', 'Brustdrücken mit Band', 'Anchor the band behind you at chest height and press both hands forward until your arms are straight. Key cue: staggered stance and tight core.', 'Befestige das Band hinter dir auf Brusthöhe und drücke beide Hände nach vorn, bis die Arme gestreckt sind. Wichtig: Schrittstellung und fester Rumpf.', '["chest"]', '["triceps","shoulders"]', 'band', 'reps', 'strength'),
('band-face-pull', 'Band Face Pull', 'Face Pull mit Band', 'Pull an anchored band towards your face while spreading your hands apart. Key cue: elbows high, finish with your knuckles pointing back.', 'Ziehe ein befestigtes Band zum Gesicht und führe dabei die Hände auseinander. Wichtig: Ellbogen hoch, am Ende zeigen die Fingerknöchel nach hinten.', '["shoulders","upper_back"]', '["traps"]', 'band', 'reps', 'strength'),
('band-curl', 'Band Curl', 'Bizeps-Curl mit Band', 'Stand on the band and curl the ends up to your shoulders. Key cue: elbows stay at your sides, lower slowly against the pull.', 'Stelle dich auf das Band und beuge die Arme bis zu den Schultern. Wichtig: Ellbogen am Körper, langsam gegen den Zug ablassen.', '["biceps"]', '["forearms"]', 'band', 'reps', 'strength'),
('band-triceps-pushdown', 'Band Triceps Pushdown', 'Trizepsdrücken mit Band', 'Anchor the band above you and push the ends down until your arms are straight. Key cue: only your forearms move.', 'Befestige das Band über dir und drücke die Enden nach unten, bis die Arme gestreckt sind. Wichtig: Nur die Unterarme bewegen sich.', '["triceps"]', '[]', 'band', 'reps', 'strength'),
('band-lateral-walk', 'Banded Lateral Walk', 'Seitwärtsgehen mit Band', 'Put a mini band around your legs, sit into a quarter squat and step sideways with tension on the band. Key cue: toes forward, never let your feet touch.', 'Lege ein Miniband um die Beine, gehe in die Viertelkniebeuge und mache Seitwärtsschritte unter Spannung. Wichtig: Zehen nach vorn, die Füße berühren sich nie.', '["glutes"]', '["adductors","quads"]', 'band', 'reps', 'strength'),
('band-pallof-press', 'Pallof Press', 'Pallof-Press', 'Stand side-on to the anchor, hold the band at your chest and press it straight out without letting it rotate you. Key cue: hips and shoulders stay square.', 'Stelle dich seitlich zur Befestigung, halte das Band vor der Brust und drücke es gerade nach vorn, ohne dich drehen zu lassen. Wichtig: Hüfte und Schultern bleiben gerade.', '["obliques","abs"]', '["shoulders"]', 'band', 'reps', 'strength'),
('cable-triceps-pushdown', 'Triceps Pushdown', 'Trizepsdrücken am Kabel', 'Grip the bar or rope on a high pulley and push it down until your arms are straight, then let it rise to chest height. Key cue: elbows glued to your sides.', 'Greife Stange oder Seil am oberen Zug und drücke nach unten, bis die Arme gestreckt sind; dann bis Brusthöhe zurück. Wichtig: Ellbogen kleben am Körper.', '["triceps"]', '[]', 'cable', 'weight_reps', 'strength'),
('cable-crossover', 'Cable Crossover', 'Cable Crossover', 'Stand between two high pulleys and bring the handles together in front of your hips in a wide arc. Key cue: slight forward lean, squeeze the chest where the hands meet.', 'Stelle dich zwischen zwei obere Züge und führe die Griffe in weitem Bogen vor der Hüfte zusammen. Wichtig: Leicht vorlehnen und die Brust anspannen, wenn die Hände sich treffen.', '["chest"]', '["shoulders"]', 'cable', 'weight_reps', 'strength')
INSERT INTO exercises (id, name_en, name_de, desc_en, desc_de, primary_muscles, secondary_muscles, equipment, tracking, category) VALUES
('cable-face-pull', 'Face Pull', 'Face Pull', 'Pull the rope from a high pulley towards your face and spread the ends apart. Key cue: elbows higher than wrists, rotate your hands back at the end.', 'Ziehe das Seil vom oberen Zug zum Gesicht und führe die Enden auseinander. Wichtig: Ellbogen höher als die Handgelenke, am Ende die Hände nach hinten drehen.', '["shoulders","upper_back"]', '["traps"]', 'cable', 'weight_reps', 'strength'),
('cable-seated-row', 'Seated Cable Row', 'Rudern am Kabelzug', 'Sit tall, pull the handle to your belly and let your shoulder blades spread again on the way back. Key cue: do not rock your torso back and forth.', 'Sitze aufrecht, ziehe den Griff zum Bauch und lasse die Schulterblätter auf dem Rückweg wieder auseinandergleiten. Wichtig: Nicht mit dem Oberkörper wippen.', '["upper_back","lats"]', '["biceps","lower_back"]', 'cable', 'weight_reps', 'strength'),
('cable-lat-pulldown', 'Lat Pulldown', 'Latzug', 'Grip the bar wider than your shoulders and pull it down to your upper chest, then let it rise under control. Key cue: pull your elbows down to your back pockets.', 'Greife die Stange weiter als schulterbreit, ziehe sie zur oberen Brust und lasse sie kontrolliert zurück. Wichtig: Ziehe die Ellbogen Richtung Gesäßtaschen.', '["lats"]', '["biceps","upper_back"]', 'cable', 'weight_reps', 'strength'),
('cable-straight-arm-pulldown', 'Straight-Arm Pulldown', 'Latzug mit gestreckten Armen', 'With straight arms, sweep the bar from a high pulley down to your thighs. Key cue: arms stay long – the movement is in the shoulders.', 'Führe die Stange vom oberen Zug mit gestreckten Armen im Bogen zu den Oberschenkeln. Wichtig: Die Arme bleiben lang – die Bewegung kommt aus der Schulter.', '["lats"]', '["triceps","abs"]', 'cable', 'weight_reps', 'strength'),
('cable-curl', 'Cable Curl', 'Bizeps-Curl am Kabel', 'Curl the bar from a low pulley up to your shoulders and lower it slowly. Key cue: constant tension, no leaning back.', 'Beuge die Arme und führe die Stange vom unteren Zug zu den Schultern, langsam ablassen. Wichtig: Dauerhafte Spannung, nicht nach hinten lehnen.', '["biceps"]', '["forearms"]', 'cable', 'weight_reps', 'strength'),
('cable-lateral-raise', 'Cable Lateral Raise', 'Seitheben am Kabel', 'Stand side-on to a low pulley and raise the handle out to the side to shoulder height. Key cue: lead with the elbow, pause at the top.', 'Stelle dich seitlich zum unteren Zug und hebe den Griff seitlich bis auf Schulterhöhe. Wichtig: Der Ellbogen führt, oben kurz halten.', '["shoulders"]', '["traps"]', 'cable', 'weight_reps', 'strength'),
('cable-crunch', 'Cable Crunch', 'Crunch am Kabel', 'Kneel under a high pulley, hold the rope beside your head and curl your ribs down towards your hips. Key cue: round your spine – your hips do not move.', 'Knie unter dem oberen Zug, halte das Seil neben dem Kopf und rolle die Rippen Richtung Hüfte ein. Wichtig: Die Wirbelsäule rundet sich – die Hüfte bleibt ruhig.', '["abs"]', '["obliques"]', 'cable', 'weight_reps', 'strength'),
('cable-woodchop', 'Cable Woodchop', 'Holzhacker am Kabel', 'Pull the handle diagonally across your body from high to low while rotating your torso. Key cue: pivot on the back foot and keep your arms long.', 'Ziehe den Griff diagonal von oben nach unten vor dem Körper und drehe den Oberkörper mit. Wichtig: Auf dem hinteren Fuß mitdrehen, die Arme bleiben lang.', '["obliques"]', '["abs","shoulders"]', 'cable', 'weight_reps', 'strength'),
('cable-pull-through', 'Cable Pull-Through', 'Cable Pull-Through', 'Face away from a low pulley with the rope between your legs, hinge back and then drive your hips forward to stand. Key cue: finish with your glutes, not by leaning back.', 'Stelle dich mit dem Rücken zum unteren Zug, das Seil zwischen den Beinen, beuge die Hüfte nach hinten und strecke sie kraftvoll. Wichtig: Mit dem Po abschließen, nicht nach hinten lehnen.', '["glutes","hamstrings"]', '["lower_back"]', 'cable', 'weight_reps', 'strength'),
('machine-leg-press', 'Leg Press', 'Beinpresse', 'Place your feet shoulder-width on the platform, lower it until your knees are bent to about 90 degrees and press back up. Key cue: lower back stays on the pad, knees never lock hard.', 'Stelle die Füße schulterbreit auf die Plattform, senke sie, bis die Knie etwa 90 Grad gebeugt sind, und drücke zurück. Wichtig: Der untere Rücken bleibt am Polster, die Knie nicht hart durchstrecken.', '["quads","glutes"]', '["hamstrings","adductors"]', 'machine', 'weight_reps', 'strength'),
('machine-hack-squat', 'Hack Squat', 'Hackenschmidt-Kniebeuge', 'With your back against the pad, squat down as deep as you can control and drive back up. Key cue: knees track over the toes, heels stay down.', 'Lehne den Rücken ans Polster, beuge die Knie so tief, wie du kontrollieren kannst, und drücke dich hoch. Wichtig: Knie folgen den Zehen, Fersen bleiben unten.', '["quads"]', '["glutes","adductors"]', 'machine', 'weight_reps', 'strength'),
('machine-leg-extension', 'Leg Extension', 'Beinstrecker', 'Sit in the machine and straighten your knees against the pad, pause, and lower slowly. Key cue: squeeze at the top, no kicking.', 'Setze dich in die Maschine und strecke die Knie gegen das Polster, kurz halten, langsam absenken. Wichtig: Oben anspannen, nicht mit Schwung treten.', '["quads"]', '[]', 'machine', 'weight_reps', 'strength'),
('machine-leg-curl', 'Leg Curl', 'Beinbeuger', 'Bend your knees against the pad to bring your heels towards your glutes, then return slowly. Key cue: hips stay pressed into the seat or bench.', 'Beuge die Knie gegen das Polster und führe die Fersen Richtung Po, dann langsam zurück. Wichtig: Die Hüfte bleibt fest auf Sitz oder Bank.', '["hamstrings"]', '["calves"]', 'machine', 'weight_reps', 'strength'),
('machine-chest-press', 'Machine Chest Press', 'Brustpresse', 'Sit with the handles at chest height and press them forward until your arms are almost straight. Key cue: shoulder blades back against the pad.', 'Setze dich so, dass die Griffe auf Brusthöhe sind, und drücke sie nach vorn, bis die Arme fast gestreckt sind. Wichtig: Schulterblätter bleiben am Polster.', '["chest"]', '["triceps","shoulders"]', 'machine', 'weight_reps', 'strength'),
('machine-pec-deck', 'Pec Deck', 'Butterfly', 'Bring the pads or handles together in front of your chest in a hugging motion and open slowly. Key cue: do not let the weight pull your shoulders forward.', 'Führe die Polster oder Griffe in einer Umarmungsbewegung vor der Brust zusammen und öffne langsam. Wichtig: Die Schultern nicht nach vorn ziehen lassen.', '["chest"]', '["shoulders"]', 'machine', 'weight_reps', 'strength'),
('machine-reverse-pec-deck', 'Reverse Pec Deck', 'Reverse Butterfly', 'Facing the pad, pull the handles apart and back in a wide arc. Key cue: slight elbow bend, squeeze the back of the shoulders.', 'Sitze mit dem Gesicht zum Polster und ziehe die Griffe in weitem Bogen nach hinten auseinander. Wichtig: Ellbogen leicht gebeugt, hintere Schulter anspannen.', '["shoulders","upper_back"]', '["traps"]', 'machine', 'weight_reps', 'strength'),
('machine-shoulder-press', 'Machine Shoulder Press', 'Schulterpresse', 'Press the handles overhead from shoulder height and lower with control. Key cue: keep your back against the pad.', 'Drücke die Griffe von Schulterhöhe über den Kopf und senke sie kontrolliert ab. Wichtig: Der Rücken bleibt am Polster.', '["shoulders"]', '["triceps"]', 'machine', 'weight_reps', 'strength'),
('machine-row', 'Machine Row', 'Rudermaschine (Kraft)', 'With your chest against the pad, pull the handles back until your elbows pass your torso. Key cue: chest stays on the pad the whole time.', 'Lehne die Brust ans Polster und ziehe die Griffe nach hinten, bis die Ellbogen hinter dem Oberkörper sind. Wichtig: Die Brust bleibt die ganze Zeit am Polster.', '["upper_back","lats"]', '["biceps"]', 'machine', 'weight_reps', 'strength'),
('machine-smith-squat', 'Smith Machine Squat', 'Kniebeuge an der Multipresse', 'Unrack the guided bar on your upper back, set your feet slightly forward and squat down, then stand. Key cue: lean into the bar and keep your whole foot planted.', 'Hebe die geführte Stange auf dem oberen Rücken aus, stelle die Füße leicht nach vorn und gehe in die Kniebeuge, dann aufstehen. Wichtig: Gegen die Stange lehnen, der ganze Fuß bleibt am Boden.', '["quads","glutes"]', '["hamstrings","adductors"]', 'machine', 'weight_reps', 'strength'),
('machine-standing-calf-raise', 'Standing Calf Raise', 'Wadenheben stehend', 'With the pads on your shoulders, rise onto your toes as high as possible and lower your heels below the step. Key cue: full stretch at the bottom, pause at the top.', 'Drücke dich mit den Polstern auf den Schultern so hoch wie möglich auf die Zehen und senke die Fersen unter die Stufe. Wichtig: Unten voll dehnen, oben kurz halten.', '["calves"]', '[]', 'machine', 'weight_reps', 'strength')
INSERT INTO exercises (id, name_en, name_de, desc_en, desc_de, primary_muscles, secondary_muscles, equipment, tracking, category) VALUES
('machine-seated-calf-raise', 'Seated Calf Raise', 'Wadenheben sitzend', 'Sit with the pad on your knees and lift your heels as high as you can, then lower slowly. Key cue: no bouncing.', 'Setze dich mit dem Polster auf den Knien und hebe die Fersen so hoch wie möglich, dann langsam absenken. Wichtig: Nicht federn.', '["calves"]', '[]', 'machine', 'weight_reps', 'strength'),
('machine-hip-abduction', 'Hip Abduction', 'Abduktorenmaschine', 'Sit in the machine and push your knees apart against the pads, then return slowly. Key cue: sit tall and control the way back.', 'Setze dich in die Maschine und drücke die Knie gegen die Polster nach außen, dann langsam zurück. Wichtig: Aufrecht sitzen und den Rückweg kontrollieren.', '["glutes"]', '[]', 'machine', 'weight_reps', 'strength'),
('machine-hip-adduction', 'Hip Adduction', 'Adduktorenmaschine', 'Sit in the machine and squeeze your knees together against the pads, then open slowly. Key cue: start with a comfortable range of motion.', 'Setze dich in die Maschine und drücke die Knie gegen die Polster zusammen, dann langsam öffnen. Wichtig: Mit einem angenehmen Bewegungsumfang beginnen.', '["adductors"]', '[]', 'machine', 'weight_reps', 'strength'),
('machine-assisted-pull-up', 'Assisted Pull-Up', 'Klimmzug mit Unterstützung', 'Kneel or stand on the assistance pad and pull yourself up until your chin clears the bar. Log the assistance weight. Key cue: start each rep by pulling your shoulders down.', 'Knie oder stehe auf dem Unterstützungspolster und ziehe dich hoch, bis das Kinn über der Stange ist. Trage das Unterstützungsgewicht ein. Wichtig: Jede Wiederholung beginnt mit dem Herunterziehen der Schultern.', '["lats"]', '["biceps","upper_back"]', 'machine', 'weight_reps', 'strength'),
('machine-back-extension', 'Back Extension', 'Rückenstrecker', 'Lock your legs into the bench, bend forward at the hips and raise your torso until your body is in a straight line. Key cue: stop at straight – do not overextend.', 'Fixiere die Beine in der Bank, beuge dich aus der Hüfte vor und richte den Oberkörper auf, bis der Körper eine Linie bildet. Wichtig: Bei gerader Linie stoppen – nicht überstrecken.', '["lower_back"]', '["glutes","hamstrings"]', 'machine', 'weight_reps', 'strength'),
('push-up', 'Push-Up', 'Liegestütz', 'From a straight-arm plank, lower your chest to just above the floor and push back up. Key cue: body in one line from head to heels – no sagging hips.', 'Senke aus dem Stütz mit gestreckten Armen die Brust bis knapp über den Boden und drücke dich wieder hoch. Wichtig: Der Körper bildet eine Linie von Kopf bis Ferse – die Hüfte hängt nicht durch.', '["chest"]', '["triceps","shoulders","abs"]', 'bodyweight', 'reps', 'strength'),
('diamond-push-up', 'Diamond Push-Up', 'Enger Liegestütz', 'Place your hands close together under your chest so thumbs and index fingers form a diamond, then do push-ups. Key cue: elbows travel back along your ribs.', 'Setze die Hände eng unter der Brust auf, sodass Daumen und Zeigefinger eine Raute bilden, und mache Liegestütze. Wichtig: Die Ellbogen gleiten an den Rippen entlang nach hinten.', '["triceps"]', '["chest","shoulders"]', 'bodyweight', 'reps', 'strength'),
('pike-push-up', 'Pike Push-Up', 'Pike-Liegestütz', 'Form an upside-down V with your hips high and lower the top of your head towards the floor between your hands. Key cue: keep your hips over your shoulders as much as possible.', 'Bilde mit hoher Hüfte ein umgedrehtes V und senke den Scheitel zwischen den Händen Richtung Boden. Wichtig: Die Hüfte bleibt möglichst über den Schultern.', '["shoulders"]', '["triceps","chest"]', 'bodyweight', 'reps', 'strength'),
('handstand-push-up', 'Handstand Push-Up', 'Handstand-Liegestütz', 'Kick up into a handstand against a wall, lower your head to the floor and press back up. Key cue: squeeze your glutes and keep your ribs tucked in.', 'Schwinge an der Wand in den Handstand, senke den Kopf zum Boden und drücke dich wieder hoch. Wichtig: Po anspannen und die Rippen einziehen.', '["shoulders"]', '["triceps","traps","abs"]', 'bodyweight', 'reps', 'strength'),
('pull-up', 'Pull-Up', 'Klimmzug', 'Hang from the bar with an overhand grip and pull yourself up until your chin is over the bar, then lower fully. Key cue: start by pulling your shoulder blades down; no kicking.', 'Hänge im Obergriff an der Stange und ziehe dich hoch, bis das Kinn über der Stange ist, dann ganz ablassen. Wichtig: Zuerst die Schulterblätter nach unten ziehen; kein Schwung mit den Beinen.', '["lats"]', '["biceps","upper_back","forearms"]', 'bodyweight', 'reps', 'strength'),
('chin-up', 'Chin-Up', 'Klimmzug im Untergriff', 'Hang with your palms facing you and pull up until your chin clears the bar. Key cue: drive your elbows down to your ribs.', 'Hänge mit den Handflächen zu dir und ziehe dich hoch, bis das Kinn über der Stange ist. Wichtig: Ziehe die Ellbogen zu den Rippen.', '["lats","biceps"]', '["upper_back","forearms"]', 'bodyweight', 'reps', 'strength'),
('muscle-up', 'Muscle-Up', 'Muscle-Up', 'Pull explosively from a hang, bring your chest over the bar and press out to straight arms. Key cue: pull the bar towards your hips, then lean forward fast.', 'Ziehe dich aus dem Hang explosiv hoch, bringe die Brust über die Stange und drücke dich in den Stütz. Wichtig: Ziehe die Stange Richtung Hüfte und lehne dich dann schnell nach vorn.', '["lats","chest","triceps"]', '["biceps","shoulders","abs"]', 'bodyweight', 'reps', 'strength'),
('dip', 'Dip', 'Dip', 'Support yourself on parallel bars, lower until your shoulders are slightly below your elbows and press back up. Key cue: shoulders stay down, away from your ears.', 'Stütze dich am Barren, senke dich, bis die Schultern knapp unter den Ellbogen sind, und drücke dich wieder hoch. Wichtig: Die Schultern bleiben unten, weg von den Ohren.', '["chest","triceps"]', '["shoulders"]', 'bodyweight', 'reps', 'strength'),
('bench-dip', 'Bench Dip', 'Bank-Dip', 'With your hands on a bench behind you and legs extended, bend your elbows to lower your hips and push back up. Key cue: keep your back close to the bench.', 'Stütze die Hände hinter dir auf eine Bank, strecke die Beine aus, beuge die Ellbogen und drücke dich wieder hoch. Wichtig: Der Rücken bleibt nah an der Bank.', '["triceps"]', '["shoulders","chest"]', 'bodyweight', 'reps', 'strength'),
('inverted-row', 'Inverted Row', 'Australischer Klimmzug', 'Hang under a low bar with your heels on the floor and pull your chest to the bar. Key cue: body stays stiff like a plank.', 'Hänge unter einer niedrigen Stange, die Fersen am Boden, und ziehe die Brust zur Stange. Wichtig: Der Körper bleibt steif wie ein Brett.', '["upper_back","lats"]', '["biceps","abs"]', 'bodyweight', 'reps', 'strength'),
('air-squat', 'Air Squat', 'Kniebeuge ohne Gewicht', 'Stand shoulder-width, sit your hips back and down until your thighs are at least parallel, then stand up. Key cue: heels down, knees out.', 'Stehe schulterbreit, setze die Hüfte nach hinten unten ab, bis die Oberschenkel mindestens waagerecht sind, und stehe auf. Wichtig: Fersen unten, Knie nach außen.', '["quads","glutes"]', '["hamstrings","adductors"]', 'bodyweight', 'reps', 'strength'),
('pistol-squat', 'Pistol Squat', 'Pistol Squat', 'Stand on one leg, extend the other in front of you and squat all the way down and up. Key cue: reach your arms forward as a counterweight.', 'Stehe auf einem Bein, strecke das andere nach vorn und gehe ganz in die Kniebeuge und wieder hoch. Wichtig: Arme als Gegengewicht nach vorn strecken.', '["quads","glutes"]', '["hamstrings","abs","adductors"]', 'bodyweight', 'reps', 'strength'),
('walking-lunge', 'Walking Lunge', 'Ausfallschritt im Gehen', 'Step forward into a lunge, lower the back knee and bring the rear leg through into the next step. Key cue: upright torso and a steady rhythm.', 'Mache einen Ausfallschritt nach vorn, senke das hintere Knie und führe das hintere Bein in den nächsten Schritt. Wichtig: Aufrechter Oberkörper und gleichmäßiger Rhythmus.', '["quads","glutes"]', '["hamstrings","adductors","calves"]', 'bodyweight', 'reps', 'strength'),
('jump-squat', 'Jump Squat', 'Sprungkniebeuge', 'Squat down and jump as high as you can, landing softly straight into the next squat. Key cue: land quietly on the whole foot.', 'Gehe in die Kniebeuge und springe so hoch du kannst; lande weich direkt in der nächsten Kniebeuge. Wichtig: Leise auf dem ganzen Fuß landen.', '["quads","glutes"]', '["calves","hamstrings"]', 'bodyweight', 'reps', 'strength'),
('box-jump', 'Box Jump', 'Box Jump', 'Swing your arms, jump onto a sturdy box and stand up fully, then step back down. Key cue: step down instead of jumping down to protect your Achilles tendons.', 'Hole mit den Armen Schwung, springe auf eine stabile Box, richte dich ganz auf und steige wieder ab. Wichtig: Absteigen statt abspringen, das schont die Achillessehnen.', '["quads","glutes"]', '["calves","hamstrings"]', 'bodyweight', 'reps', 'strength')
INSERT INTO exercises (id, name_en, name_de, desc_en, desc_de, primary_muscles, secondary_muscles, equipment, tracking, category) VALUES
('glute-bridge', 'Glute Bridge', 'Glute Bridge', 'Lie on your back with bent knees and lift your hips until your body forms a line from knees to shoulders. Key cue: push through your heels and squeeze at the top.', 'Lege dich mit angewinkelten Beinen auf den Rücken und hebe die Hüfte, bis Knie, Hüfte und Schultern eine Linie bilden. Wichtig: Über die Fersen drücken und oben anspannen.', '["glutes"]', '["hamstrings","lower_back"]', 'bodyweight', 'reps', 'strength'),
('nordic-curl', 'Nordic Curl', 'Nordic Curl', 'Kneel with your ankles anchored and lower your straight body towards the floor as slowly as you can, then push back up. Key cue: hips stay extended – do not fold at the waist.', 'Knie mit fixierten Fußgelenken und senke den gestreckten Körper so langsam wie möglich Richtung Boden, dann drücke dich zurück. Wichtig: Die Hüfte bleibt gestreckt – nicht einknicken.', '["hamstrings"]', '["glutes","calves"]', 'bodyweight', 'reps', 'strength'),
('bodyweight-calf-raise', 'Calf Raise', 'Wadenheben', 'Stand on the edge of a step, rise onto your toes and lower your heels below the edge. Key cue: slow and full range, one leg at a time for more load.', 'Stelle dich auf eine Stufenkante, drücke dich auf die Zehen und senke die Fersen unter die Kante. Wichtig: Langsam und über den vollen Weg, einbeinig für mehr Last.', '["calves"]', '[]', 'bodyweight', 'reps', 'strength'),
('plank', 'Plank', 'Unterarmstütz', 'Support yourself on forearms and toes and hold your body in a straight line. Key cue: squeeze glutes and abs, do not let your hips sag or pike.', 'Stütze dich auf Unterarme und Zehen und halte den Körper in einer geraden Linie. Wichtig: Po und Bauch anspannen, die Hüfte weder durchhängen lassen noch hochschieben.', '["abs"]', '["obliques","shoulders","lower_back"]', 'bodyweight', 'time', 'strength'),
('side-plank', 'Side Plank', 'Seitstütz', 'Lie on your side, prop yourself on one forearm and lift your hips so your body is straight. Key cue: push the floor away and keep the top hip stacked.', 'Lege dich auf die Seite, stütze dich auf einen Unterarm und hebe die Hüfte, bis der Körper gerade ist. Wichtig: Den Boden wegdrücken und die obere Hüfte über der unteren halten.', '["obliques"]', '["abs","shoulders","glutes"]', 'bodyweight', 'time', 'strength'),
('hollow-hold', 'Hollow Hold', 'Hollow Hold', 'Lie on your back, press your lower back into the floor and lift arms, shoulders and legs slightly off the ground. Key cue: if your lower back lifts, raise your legs higher.', 'Lege dich auf den Rücken, drücke den unteren Rücken in den Boden und hebe Arme, Schultern und Beine leicht an. Wichtig: Löst sich der untere Rücken, hebe die Beine höher.', '["abs"]', '["obliques"]', 'bodyweight', 'time', 'strength'),
('wall-sit', 'Wall Sit', 'Wandsitzen', 'Lean against a wall and slide down until your knees are at 90 degrees, then hold. Key cue: whole back against the wall, hands off your thighs.', 'Lehne dich an eine Wand und rutsche herunter, bis die Knie 90 Grad gebeugt sind; halte die Position. Wichtig: Der ganze Rücken liegt an, die Hände stützen nicht auf den Oberschenkeln.', '["quads"]', '["glutes","calves"]', 'bodyweight', 'time', 'strength'),
('hanging-leg-raise', 'Hanging Leg Raise', 'Beinheben im Hang', 'Hang from a bar and raise your straight legs to hip height or higher, then lower slowly. Key cue: no swinging – curl your pelvis up.', 'Hänge an einer Stange und hebe die gestreckten Beine auf Hüfthöhe oder höher, dann langsam absenken. Wichtig: Nicht schwingen – das Becken einrollen.', '["abs"]', '["obliques","forearms"]', 'bodyweight', 'reps', 'strength'),
('crunch', 'Crunch', 'Crunch', 'Lie on your back with bent knees and curl your shoulders off the floor towards your hips. Key cue: lower back stays down, do not pull on your neck.', 'Lege dich mit angewinkelten Beinen auf den Rücken und rolle die Schultern Richtung Hüfte vom Boden ab. Wichtig: Der untere Rücken bleibt liegen, nicht am Nacken ziehen.', '["abs"]', '[]', 'bodyweight', 'reps', 'strength'),
('sit-up', 'Sit-Up', 'Sit-up', 'From lying with bent knees, sit all the way up and roll back down with control. Key cue: roll up vertebra by vertebra instead of throwing yourself up.', 'Richte dich aus der Rückenlage mit angewinkelten Beinen ganz auf und rolle kontrolliert wieder ab. Wichtig: Wirbel für Wirbel aufrollen statt hochwerfen.', '["abs"]', '["obliques"]', 'bodyweight', 'reps', 'strength'),
('bicycle-crunch', 'Bicycle Crunch', 'Fahrrad-Crunch', 'On your back, alternate bringing one elbow towards the opposite knee while the other leg extends. Key cue: rotate the ribcage, not just the elbows.', 'Führe in Rückenlage abwechselnd einen Ellbogen zum gegenüberliegenden Knie, während das andere Bein gestreckt wird. Wichtig: Den Brustkorb drehen, nicht nur die Ellbogen.', '["obliques","abs"]', '[]', 'bodyweight', 'reps', 'strength'),
('russian-twist', 'Russian Twist', 'Russian Twist', 'Sit with your torso leaned back and feet light, and rotate your shoulders from side to side. Key cue: long spine, the chest turns with the hands.', 'Sitze mit zurückgelehntem Oberkörper und leichten Füßen und drehe die Schultern von Seite zu Seite. Wichtig: Lange Wirbelsäule, die Brust dreht sich mit den Händen.', '["obliques"]', '["abs"]', 'bodyweight', 'reps', 'strength'),
('mountain-climber', 'Mountain Climbers', 'Bergsteiger', 'In a straight-arm plank, drive your knees alternately towards your chest at a running pace. Key cue: hips stay low and shoulders over the hands.', 'Ziehe im Stütz mit gestreckten Armen die Knie abwechselnd im Lauftempo zur Brust. Wichtig: Die Hüfte bleibt tief, die Schultern über den Händen.', '["abs"]', '["shoulders","quads","obliques"]', 'bodyweight', 'time', 'strength'),
('burpee', 'Burpee', 'Burpee', 'Drop your hands to the floor, kick back into a push-up, jump your feet forward and leap up with a clap overhead. Key cue: find a rhythm you can keep rather than sprinting the first five.', 'Setze die Hände auf, springe in den Liegestütz, springe mit den Füßen wieder vor und strecke dich mit einem Klatscher über dem Kopf in die Luft. Wichtig: Lieber ein haltbares Tempo finden, als die ersten fünf zu sprinten.', '["quads","chest"]', '["shoulders","triceps","abs","glutes","calves"]', 'bodyweight', 'reps', 'strength'),
('superman', 'Superman', 'Superman', 'Lie face down and lift your arms, chest and legs off the floor at the same time, pause and lower. Key cue: look at the floor to keep your neck long.', 'Lege dich auf den Bauch und hebe Arme, Brust und Beine gleichzeitig vom Boden, kurz halten, absenken. Wichtig: Blick zum Boden, damit der Nacken lang bleibt.', '["lower_back"]', '["glutes","upper_back"]', 'bodyweight', 'reps', 'strength'),
('neck-isometric-hold', 'Neck Isometric Hold', 'Isometrisches Nackenhalten', 'Press your head against your hand (front, back and each side) without letting it move, and hold. Key cue: build pressure gradually – never jerk.', 'Drücke den Kopf gegen deine Hand (vorn, hinten und zu beiden Seiten), ohne dass er sich bewegt, und halte. Wichtig: Den Druck langsam aufbauen – niemals ruckartig.', '["neck"]', '["traps"]', 'bodyweight', 'time', 'strength'),
('running', 'Running', 'Laufen', 'Run outdoors at a pace that fits your goal and log distance and time. Key cue: quick, light steps landing under your hips, relaxed shoulders.', 'Laufe draußen in einem Tempo, das zu deinem Ziel passt, und trage Strecke und Zeit ein. Wichtig: Schnelle, leichte Schritte unter der Hüfte, lockere Schultern.', '["quads","hamstrings","calves"]', '["glutes","abs"]', 'cardio', 'distance_time', 'cardio'),
('treadmill-running', 'Treadmill Run', 'Laufband', 'Run on the treadmill and log distance and time. Key cue: set a 1% incline to mimic outdoor running and do not hold the rails.', 'Laufe auf dem Laufband und trage Strecke und Zeit ein. Wichtig: 1 % Steigung simuliert das Laufen im Freien; nicht an den Griffen festhalten.', '["quads","hamstrings","calves"]', '["glutes","abs"]', 'cardio', 'distance_time', 'cardio'),
('walking', 'Walking', 'Gehen', 'Walk briskly and log distance and time. Key cue: stand tall and swing your arms – it counts, especially on rest days.', 'Gehe zügig und trage Strecke und Zeit ein. Wichtig: Aufrecht gehen und die Arme mitschwingen – das zählt, gerade an Ruhetagen.', '["calves","glutes"]', '["quads","hamstrings"]', 'cardio', 'distance_time', 'cardio'),
('hiking', 'Hiking', 'Wandern', 'Hike on trails or hills and log distance and time. Key cue: shorten your stride uphill and keep a pace at which you can still talk.', 'Wandere auf Wegen oder im Gelände und trage Strecke und Zeit ein. Wichtig: Bergauf kürzere Schritte und ein Tempo, bei dem du noch reden kannst.', '["quads","glutes","calves"]', '["hamstrings","abs"]', 'cardio', 'distance_time', 'cardio')
INSERT INTO exercises (id, name_en, name_de, desc_en, desc_de, primary_muscles, secondary_muscles, equipment, tracking, category) VALUES
('cycling', 'Cycling', 'Radfahren', 'Ride outdoors and log distance and time. Key cue: keep a smooth cadence of around 80–90 rpm instead of grinding a heavy gear.', 'Fahre draußen Rad und trage Strecke und Zeit ein. Wichtig: Lieber eine runde Trittfrequenz von etwa 80–90 Umdrehungen als einen zu schweren Gang.', '["quads"]', '["glutes","hamstrings","calves"]', 'cardio', 'distance_time', 'cardio'),
('stationary-bike', 'Stationary Bike', 'Ergometer', 'Pedal on an indoor bike and log distance and time. Key cue: set the saddle so your knee is slightly bent at the bottom of the stroke.', 'Fahre auf dem Ergometer und trage Strecke und Zeit ein. Wichtig: Den Sattel so einstellen, dass das Knie am tiefsten Punkt leicht gebeugt ist.', '["quads"]', '["glutes","hamstrings","calves"]', 'cardio', 'distance_time', 'cardio'),
('rowing-machine', 'Rowing Machine', 'Rudergerät', 'Row on the ergometer and log distance and time. Key cue: the order is legs, then body, then arms – and the reverse on the way back.', 'Rudere auf dem Ergometer und trage Strecke und Zeit ein. Wichtig: Erst Beine, dann Oberkörper, dann Arme – und zurück in umgekehrter Reihenfolge.', '["upper_back","quads","lats"]', '["hamstrings","glutes","biceps","abs","lower_back"]', 'cardio', 'distance_time', 'cardio'),
('swimming', 'Swimming', 'Schwimmen', 'Swim laps in any stroke and log distance and time. Key cue: long strokes and a steady breathing rhythm beat thrashing.', 'Schwimme Bahnen in beliebigem Stil und trage Strecke und Zeit ein. Wichtig: Lange Züge und ein ruhiger Atemrhythmus schlagen wildes Paddeln.', '["lats","shoulders"]', '["triceps","chest","abs","quads","upper_back"]', 'cardio', 'distance_time', 'cardio'),
('elliptical', 'Elliptical', 'Crosstrainer', 'Stride on the elliptical trainer and log distance and time. Key cue: push and pull the handles actively and stay upright.', 'Trainiere auf dem Crosstrainer und trage Strecke und Zeit ein. Wichtig: Die Griffe aktiv drücken und ziehen und aufrecht bleiben.', '["quads","glutes"]', '["hamstrings","calves","shoulders"]', 'cardio', 'distance_time', 'cardio'),
('ski-erg', 'Ski Erg', 'Ski-Ergometer', 'Pull both handles down past your hips with a powerful hinge, then reach tall again. Key cue: use your body weight, not just your arms.', 'Ziehe beide Griffe mit kräftigem Hüftknick an der Hüfte vorbei nach unten und strecke dich wieder. Wichtig: Das Körpergewicht einsetzen, nicht nur die Arme.', '["lats","abs"]', '["triceps","shoulders","glutes","hamstrings"]', 'cardio', 'distance_time', 'cardio'),
('stair-climber', 'Stair Climber', 'Stepper', 'Climb on the stair machine and log the duration and how hard it felt. Key cue: stand upright and stay off the handrails.', 'Steige auf dem Stepper und trage Dauer und gefühlte Anstrengung ein. Wichtig: Aufrecht stehen und nicht auf die Griffe stützen.', '["quads","glutes"]', '["calves","hamstrings"]', 'cardio', 'duration_rpe', 'cardio'),
('jump-rope', 'Jump Rope', 'Seilspringen', 'Skip rope continuously or in intervals and log duration and effort. Key cue: small jumps, the rope turns from the wrists.', 'Springe Seil am Stück oder in Intervallen und trage Dauer und Anstrengung ein. Wichtig: Kleine Sprünge, das Seil dreht aus den Handgelenken.', '["calves"]', '["shoulders","forearms","quads","abs"]', 'cardio', 'duration_rpe', 'cardio'),
('hiit', 'HIIT Session', 'HIIT-Einheit', 'Alternate short all-out efforts with brief rests, for example 30 seconds on and 30 seconds off. Log total duration and effort. Key cue: quality over quantity – stop a round when your form breaks down.', 'Wechsle kurze, maximale Belastungen mit kurzen Pausen ab, zum Beispiel 30 Sekunden Belastung und 30 Sekunden Pause. Trage Gesamtdauer und Anstrengung ein. Wichtig: Qualität vor Menge – brich eine Runde ab, wenn die Technik leidet.', '["quads","glutes"]', '["abs","shoulders","calves","chest","hamstrings"]', 'cardio', 'duration_rpe', 'cardio'),
('air-bike', 'Air Bike', 'Air Bike', 'Push and pull the handles while pedalling against the fan resistance. Log duration and effort. Key cue: drive with arms and legs together – the harder you go, the harder it gets.', 'Drücke und ziehe die Griffe und tritt gleichzeitig gegen den Luftwiderstand. Trage Dauer und Anstrengung ein. Wichtig: Arme und Beine arbeiten zusammen – je härter du trittst, desto schwerer wird es.', '["quads","shoulders"]', '["glutes","hamstrings","chest","upper_back","abs"]', 'cardio', 'duration_rpe', 'cardio'),
('sled-push', 'Sled Push', 'Schlittenschieben', 'Lean into the loaded sled with straight arms and drive it forward with short, powerful steps; one length counts as one rep. Key cue: body at 45 degrees, hips low.', 'Lehne dich mit gestreckten Armen gegen den beladenen Schlitten und schiebe ihn mit kurzen, kräftigen Schritten; eine Bahn zählt als eine Wiederholung. Wichtig: Körper im 45-Grad-Winkel, Hüfte tief.', '["quads","glutes"]', '["calves","hamstrings","shoulders","abs"]', 'other', 'weight_reps', 'strength'),
('rugby-training-session', 'Rugby Training Session', 'Rugby-Training', 'A full team session with warm-up, skills, contact and conditioning. Log the total duration and how hard it felt (RPE). Key cue: warm up your shoulders and neck before any contact.', 'Eine komplette Mannschaftseinheit mit Aufwärmen, Technik, Kontakt und Kondition. Trage die Gesamtdauer und die gefühlte Anstrengung (RPE) ein. Wichtig: Schultern und Nacken vor jedem Kontakt aufwärmen.', '["quads","glutes","hamstrings"]', '["shoulders","calves","abs","upper_back","neck","traps"]', 'rugby', 'duration_rpe', 'rugby'),
('rugby-match', 'Rugby Match', 'Rugby-Spiel', 'Match day. Log your minutes on the pitch and the effort. Key cue: recovery starts at the final whistle – drink, eat and cool down.', 'Spieltag. Trage deine Minuten auf dem Platz und die Anstrengung ein. Wichtig: Die Erholung beginnt mit dem Schlusspfiff – trinken, essen, auslaufen.', '["quads","glutes","hamstrings"]', '["shoulders","calves","abs","upper_back","neck","traps","chest"]', 'rugby', 'duration_rpe', 'rugby'),
('touch-rugby', 'Touch Rugby', 'Touch-Rugby', 'Non-contact rugby with lots of running, stepping and passing. Log duration and effort. Key cue: keep scanning and communicate – it is conditioning in disguise.', 'Kontaktloses Rugby mit viel Laufen, Haken und Passen. Trage Dauer und Anstrengung ein. Wichtig: Den Überblick behalten und reden – Konditionstraining in Verkleidung.', '["quads","calves","hamstrings"]', '["glutes","abs"]', 'rugby', 'duration_rpe', 'rugby'),
('rugby-sprints', 'Sprints', 'Sprints', 'Sprint a set distance (10–60 m) at full speed with complete rest in between; log each sprint as distance and time. Key cue: drive low for the first steps and warm up thoroughly – hamstrings do not forgive.', 'Sprinte eine feste Strecke (10–60 m) mit voller Geschwindigkeit und vollständiger Pause dazwischen; trage jeden Sprint mit Strecke und Zeit ein. Wichtig: Die ersten Schritte flach antreten und gründlich aufwärmen – die Beinrückseite verzeiht nichts.', '["hamstrings","quads","glutes"]', '["calves","abs"]', 'rugby', 'distance_time', 'rugby'),
('rugby-shuttle-runs', 'Shuttle Runs', 'Pendelläufe', 'Run back and forth between lines (for example 20–40–60 m) and log total distance and time. Key cue: get low and plant the outside foot to turn.', 'Laufe zwischen Linien hin und her (zum Beispiel 20–40–60 m) und trage Gesamtstrecke und Zeit ein. Wichtig: Zum Wenden tief gehen und den äußeren Fuß setzen.', '["quads","hamstrings","calves"]', '["glutes","abs","adductors"]', 'rugby', 'distance_time', 'rugby'),
('rugby-tackle-bag', 'Tackle Bag Drills', 'Tackle-Bag-Drills', 'Hit the tackle bag with good technique, wrap and drive it back; count each tackle as a rep. Key cue: cheek to cheek – head to the side, eyes up, short steps into contact.', 'Triff den Tackle-Bag mit sauberer Technik, umklammere ihn und schiebe ihn zurück; jeder Tackle zählt als Wiederholung. Wichtig: Kopf zur Seite, Blick nach oben, mit kurzen Schritten in den Kontakt.', '["shoulders","quads","glutes"]', '["abs","neck","traps","chest","upper_back"]', 'rugby', 'reps', 'rugby'),
('rugby-scrum-machine', 'Scrum Machine', 'Gedränge-Maschine', 'Bind onto the scrum machine, set your body position and drive it with your pack; count each engagement as a rep. Key cue: flat back, hips below shoulders, chin off your chest.', 'Binde an der Gedränge-Maschine, baue die Körperposition auf und schiebe mit deinem Sturm; jedes Anbinden zählt als Wiederholung. Wichtig: Gerader Rücken, Hüfte unter Schulterhöhe, Kinn weg von der Brust.', '["quads","glutes","lower_back"]', '["neck","traps","shoulders","hamstrings","abs","calves"]', 'rugby', 'reps', 'rugby'),
('rugby-ruck-drills', 'Rucking & Contact Drills', 'Ruck- und Kontakt-Drills', 'Clean-outs, ruck entries and contact work with pads or partners. Log duration and effort. Key cue: enter low through the gate and stay on your feet.', 'Clean-outs, Ruck-Einstiege und Kontaktarbeit mit Pads oder Partnern. Trage Dauer und Anstrengung ein. Wichtig: Tief durch das Gate kommen und auf den Füßen bleiben.', '["quads","glutes","shoulders"]', '["abs","lower_back","neck","traps","upper_back"]', 'rugby', 'duration_rpe', 'rugby'),
('rugby-jackal-drills', 'Jackal Drills', 'Jackal-Drills', 'Get over the tackled player or bag in a strong, low stance and rip the ball; count each steal as a rep. Key cue: support your own body weight and keep your head above your hips.', 'Stelle dich stabil und tief über den getackelten Spieler oder Sack und erobere den Ball; jeder Ballgewinn zählt als Wiederholung. Wichtig: Das eigene Gewicht tragen und den Kopf über der Hüfte halten.', '["hamstrings","glutes","lower_back"]', '["forearms","neck","abs","quads"]', 'rugby', 'reps', 'rugby')
INSERT INTO exercises (id, name_en, name_de, desc_en, desc_de, primary_muscles, secondary_muscles, equipment, tracking, category) VALUES
('rugby-maul-drills', 'Maul Drills', 'Paket-Drills', 'Set up and drive mauls as a unit, working on binding and leg drive. Log duration and effort. Key cue: bind tight, stay square and take short steps.', 'Baut als Einheit Pakete auf und schiebt sie, mit Fokus auf Bindung und Beinarbeit. Trage Dauer und Anstrengung ein. Wichtig: Eng binden, gerade bleiben und kurze Schritte machen.', '["quads","glutes","upper_back"]', '["shoulders","abs","lower_back","forearms","calves"]', 'rugby', 'duration_rpe', 'rugby'),
('rugby-passing-drills', 'Passing Drills', 'Pass-Drills', 'Pass off both hands while standing, running lines and under pressure. Log duration and effort. Key cue: hands up as a target, follow through towards the receiver.', 'Passe über beide Seiten im Stand, im Lauf und unter Druck. Trage Dauer und Anstrengung ein. Wichtig: Hände als Ziel zeigen und zum Empfänger durchschwingen.', '["forearms","obliques"]', '["shoulders","abs","quads"]', 'rugby', 'duration_rpe', 'rugby'),
('rugby-kicking-practice', 'Kicking Practice', 'Kick-Training', 'Punts, grubbers, drop kicks and place kicks. Log duration and effort. Key cue: eyes on the ball through contact and follow through towards the target.', 'Punts, Grubber, Dropkicks und Platzkicks. Trage Dauer und Anstrengung ein. Wichtig: Den Ball bis zum Treffpunkt ansehen und zum Ziel durchschwingen.', '["quads","adductors"]', '["hamstrings","abs","glutes","calves"]', 'rugby', 'duration_rpe', 'rugby'),
('rugby-lineout-lifts', 'Lineout Lifts', 'Gassen-Lifts', 'Practise lifting or jumping in the lineout; count each lift as a rep. Key cue: lifters squat and drive straight up together, lock the arms out and bring the jumper down safely.', 'Übt das Heben oder Springen in der Gasse; jeder Lift zählt als Wiederholung. Wichtig: Die Heber gehen gemeinsam tief und drücken senkrecht nach oben, strecken die Arme und setzen den Springer sicher ab.', '["shoulders","quads","glutes"]', '["triceps","abs","calves","traps"]', 'rugby', 'reps', 'rugby'),
('rugby-down-ups', 'Down-Ups', 'Down-Ups', 'Drop chest-first to the ground and get back to your feet as fast as possible, as after a tackle. Key cue: push the ground away and bring your feet under you in one move.', 'Lasse dich mit der Brust auf den Boden fallen und komme so schnell wie möglich wieder auf die Füße – wie nach einem Tackle. Wichtig: Den Boden wegdrücken und die Füße in einer Bewegung unter den Körper bringen.', '["chest","quads"]', '["shoulders","abs","triceps","glutes"]', 'rugby', 'reps', 'rugby'),
('rugby-agility-footwork', 'Agility & Footwork', 'Agilität & Beinarbeit', 'Ladder work, cone drills and side-steps at game speed. Log duration and effort. Key cue: stay on the balls of your feet with your hips low.', 'Koordinationsleiter, Hütchen-Drills und Sidesteps in Spielgeschwindigkeit. Trage Dauer und Anstrengung ein. Wichtig: Auf den Fußballen bleiben, die Hüfte tief.', '["calves","quads"]', '["adductors","glutes","hamstrings","abs"]', 'rugby', 'duration_rpe', 'rugby'),
('rugby-wrestling', 'Contact Wrestling', 'Kontakt-Ringen', 'Partner grappling for contact fitness: pummelling, hand fighting and controlled takedowns. Log duration and effort. Key cue: win the body height battle and agree on the intensity beforehand.', 'Ringen mit Partner für die Kontaktfitness: Griffkampf, Pummeln und kontrollierte Takedowns. Trage Dauer und Anstrengung ein. Wichtig: Den Kampf um die Körperhöhe gewinnen und die Intensität vorher absprechen.', '["upper_back","glutes","abs"]', '["forearms","neck","shoulders","quads","biceps","traps"]', 'rugby', 'duration_rpe', 'rugby')
